steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{"query": "{
  teams(filter: {name: {eq: "Mobile"}}) { nodes { id name } }
  users(filter: {name: {contains: "Priya Nair"}}) { nodes { id name } }
  workflowStates(filter: {name: {eq: "In Review"}}) { nodes { id name team { id name } } }
}"}'
